import sys, heapq
from collections import deque

def main():
    data = sys.stdin.buffer.read().split()
    n = int(data[0]); m = int(data[1]); S = int(data[2]); T = int(data[3])
    adj = [[] for _ in range(n + 1)]
    p = 4
    for _ in range(m):
        u = int(data[p]); v = int(data[p + 1]); p += 2
        adj[u].append(v)
        adj[v].append(u)

    def bfs(src):
        dist = [-1] * (n + 1)
        dist[src] = 0
        order = [src]
        dq = deque([src])
        while dq:
            v = dq.popleft()
            for w in adj[v]:
                if dist[w] < 0:
                    dist[w] = dist[v] + 1
                    order.append(w)
                    dq.append(w)
        return dist, order

    dS, order = bfs(S)
    dT, _ = bfs(T)
    d = dS[T]
    cnt = [0] * (n + 1)
    cnt[S] = 1
    for v in order:
        cv = cnt[v]
        if cv == 0:
            continue
        for w in adj[v]:
            if dS[w] == dS[v] + 1:
                c = cnt[w] + cv
                cnt[w] = 2 if c > 2 else c
    if cnt[T] >= 2:
        print(2 * d)
        return

    idx = [-1] * (n + 1)
    for v in range(1, n + 1):
        if dS[v] + dT[v] == d:
            idx[v] = dS[v]

    INF = float('inf')
    best = INF
    # (ii) and (iii)
    for v in range(1, n + 1):
        if len(adj[v]) >= 3:
            if 0 < idx[v] < d:
                best = min(best, 2)
            c = 4 * min(dS[v], dT[v]) + 4
            if c < best:
                best = c

    # (i) cycle detours
    OFF = n + 5
    B = n + 1

    def run(sign):
        res = [[] for _ in range(n + 1)]
        heap = []
        for u in range(1, n + 1):
            i = idx[u]
            if i < 0:
                continue
            base = i if sign == 1 else -i
            for v in adj[u]:
                if idx[v] < 0:
                    heap.append((((base + 1 + OFF) * B + v) * B + i))
        heapq.heapify(heap)
        while heap:
            key = heapq.heappop(heap)
            src = key % B
            key //= B
            v = key % B
            val = key // B - OFF
            r = res[v]
            if len(r) >= 2:
                continue
            ok = True
            for (_, s) in r:
                if s == src:
                    ok = False
                    break
            if not ok:
                continue
            r.append((val, src))
            nv = val + 1
            for w in adj[v]:
                if idx[w] >= 0:
                    continue
                rw = res[w]
                if len(rw) >= 2:
                    continue
                dup = False
                for (_, s) in rw:
                    if s == src:
                        dup = True
                        break
                if dup:
                    continue
                heapq.heappush(heap, ((nv + OFF) * B + w) * B + src)
        return res

    F = run(1)
    H = run(-1)
    for v in range(1, n + 1):
        if idx[v] >= 0:
            continue
        for (fv, fs) in F[v]:
            for (hv, hs) in H[v]:
                if fs != hs:
                    c = fv + hv
                    if c < best:
                        best = c

    if best == INF:
        print(-1)
    else:
        print(2 * d + best)

main()
```

