import sys

MOD = 998244353

def main():
    input = sys.stdin.readline
    N = int(input())
    A = list(map(int, input().split()))

    # Store p-adic exponents of every A_i for each prime p.
    exps = {}

    for i, x in enumerate(A):
        v = x
        d = 2
        while d * d <= v:
            if v % d == 0:
                cnt = 0
                while v % d == 0:
                    v //= d
                    cnt += 1
                if d not in exps:
                    exps[d] = [0] * (N - 1)
                exps[d][i] = cnt
            d += 1
        if v > 1:
            if v not in exps:
                exps[v] = [0] * (N - 1)
            exps[v][i] = 1

    answer = 1

    for p, a_list in exps.items():
        total_step = sum(a_list)
        L = total_step + 1

        # p^h for h = 0..total_step
        pw = [1] * L
        for h in range(1, L):
            pw[h] = pw[h - 1] * p % MOD

        # dp0[h]: current exponent is h, and zero has not appeared yet.
        # dp1[h]: current exponent is h, and zero has appeared at least once.
        dp0 = [0] * L
        dp1 = [0] * L

        # At S_1, exponent h contributes p^h to the score.
        dp1[0] = 1
        for h in range(1, L):
            dp0[h] = pw[h]

        for a in a_list:
            ndp0 = [0] * L
            ndp1 = [0] * L

            if a == 0:
                # Exponent stays unchanged.
                for h in range(L):
                    w = pw[h]
                    ndp0[h] = dp0[h] * w % MOD
                    ndp1[h] = dp1[h] * w % MOD
            else:
                # Move upward: h -> h + a
                for h in range(L - a):
                    t = h + a
                    w = pw[t]

                    if dp0[h]:
                        ndp0[t] = (ndp0[t] + dp0[h] * w) % MOD
                    if dp1[h]:
                        ndp1[t] = (ndp1[t] + dp1[h] * w) % MOD

                # Move downward: h -> h - a
                for h in range(a, L):
                    t = h - a
                    w = pw[t]

                    if t == 0:
                        val = dp0[h] + dp1[h]
                        if val:
                            ndp1[0] = (ndp1[0] + val * w) % MOD
                    else:
                        if dp0[h]:
                            ndp0[t] = (ndp0[t] + dp0[h] * w) % MOD
                        if dp1[h]:
                            ndp1[t] = (ndp1[t] + dp1[h] * w) % MOD

            dp0, dp1 = ndp0, ndp1

        # gcd condition means the minimum exponent for this prime must be 0.
        contribution = sum(dp1) % MOD
        answer = answer * contribution % MOD

    print(answer)

if __name__ == "__main__":
    main()
