import sys

MOD = 998244353

def main():
    data = sys.stdin.buffer.read().split()
    N = int(data[0])
    M = int(data[1])
    S = [c - 97 for c in data[2]]

    states = 1 << N

    # trans[mask][c] = next DP-state mask after appending character c
    trans = [[0] * 26 for _ in range(states)]

    for mask in range(states):
        old = [0] * (N + 1)
        for i in range(N):
            old[i + 1] = old[i] + ((mask >> i) & 1)

        for c in range(26):
            new = [0] * (N + 1)
            next_mask = 0

            for i in range(1, N + 1):
                best = old[i]
                if new[i - 1] > best:
                    best = new[i - 1]
                if S[i - 1] == c:
                    candidate = old[i - 1] + 1
                    if candidate > best:
                        best = candidate

                new[i] = best
                if new[i] > new[i - 1]:
                    next_mask |= 1 << (i - 1)

            trans[mask][c] = next_mask

    dp = [0] * states
    dp[0] = 1

    for _ in range(M):
        ndp = [0] * states
        for mask, value in enumerate(dp):
            if value == 0:
                continue
            for nxt in trans[mask]:
                ndp[nxt] += value
                if ndp[nxt] >= MOD:
                    ndp[nxt] -= MOD
        dp = ndp

    ans = [0] * (N + 1)
    for mask, value in enumerate(dp):
        ans[mask.bit_count()] += value
        if ans[mask.bit_count()] >= MOD:
            ans[mask.bit_count()] -= MOD

    print(*ans)

