import sys

MOD = 998244353

def compose(a, b):
    # Relation a: start -> middle, relation b: middle -> end
    # Returns relation start -> end
    res = 0
    for x in range(2):
        for y in range(2):
            if (a >> (x * 2 + y)) & 1:
                for z in range(2):
                    if (b >> (y * 2 + z)) & 1:
                        res |= 1 << (x * 2 + z)
    return res

def main():
    input = sys.stdin.readline
    N = int(input())
    s = input().strip()

    comp = [[0] * 16 for _ in range(16)]
    for a in range(16):
        for b in range(16):
            comp[a][b] = compose(a, b)

    # Possible relations for one position.
    # Bit x*2+y means transition x -> y.
    # s_i = 0:
    # a_i = x_i - x_{i-1}
    zero_relations = [
        4,   # a_i = -1: 1 -> 0
        9,   # a_i =  0: 0 -> 0, 1 -> 1
        2,   # a_i =  1: 0 -> 1
    ]

    # s_i = 1:
    # a_i = x_i - x_{i-1} - y_i, y_i in {0,1}
    one_relations = [
        4,   # a_i = -2
        13,  # a_i = -1
        11,  # a_i =  0
        2,   # a_i =  1
    ]

    # Initially, the relation is identity.
    dp = [0] * 16
    dp[9] = 1

    for ch in s:
        choices = one_relations if ch == '1' else zero_relations
        ndp = [0] * 16
        for cur, ways in enumerate(dp):
            if ways == 0:
                continue
            for local in choices:
                nxt = comp[cur][local]
                ndp[nxt] += ways
                if ndp[nxt] >= MOD:
                    ndp[nxt] -= MOD
        dp = ndp

    # A cyclic assignment exists iff the final relation has
    # a fixed point: 0 -> 0 or 1 -> 1.
    ans = 0
    for rel, ways in enumerate(dp):
        if (rel & 1) or (rel & 8):
            ans += ways

    print(ans % MOD)

if __name__ == "__main__":
    main()
