import sys

def solve():
    data = list(map(int, sys.stdin.buffer.read().split()))
    it = iter(data)
    t = next(it)
    out = []

    for _ in range(t):
        n = next(it)
        a = [next(it) for _ in range(2 * n)]

        pos1 = [-1] * (n + 1)
        pos2 = [-1] * (n + 1)

        for i, x in enumerate(a):
            if pos1[x] == -1:
                pos1[x] = i
            else:
                pos2[x] = i

        non_adjacent = [False] * (n + 1)
        for x in range(1, n + 1):
            non_adjacent[x] = (pos2[x] - pos1[x] != 1)

        first_edge = {}
        counted = set()
        ans = 0

        for i in range(2 * n - 1):
            x, y = a[i], a[i + 1]
            if x == y:
                continue

            if x > y:
                x, y = y, x

            if not (non_adjacent[x] and non_adjacent[y]):
                continue

            key = x * (n + 1) + y

            if key in counted:
                continue

            if key in first_edge:
                if i - first_edge[key] >= 2:
                    ans += 1
                    counted.add(key)
            else:
