import sys

MOD = 998244353
G = 3

def ntt(a, invert=False):
    n = len(a)

    j = 0
    for i in range(1, n):
        bit = n >> 1
        while j & bit:
            j ^= bit
            bit >>= 1
        j ^= bit
        if i < j:
            a[i], a[j] = a[j], a[i]

    length = 2
    while length <= n:
        wlen = pow(G, (MOD - 1) // length, MOD)
        if invert:
            wlen = pow(wlen, MOD - 2, MOD)

        half = length >> 1
        for start in range(0, n, length):
            w = 1
            end = start + half
            for i in range(start, end):
                u = a[i]
                v = a[i + half] * w % MOD
                a[i] = (u + v) % MOD
                a[i + half] = (u - v) % MOD
                w = w * wlen % MOD

        length <<= 1

    if invert:
        inv_n = pow(n, MOD - 2, MOD)
        for i in range(n):
            a[i] = a[i] * inv_n % MOD


def convolution(a, b):
    if not a or not b:
        return []

    need = len(a) + len(b) - 1

    if min(len(a), len(b)) <= 40:
        res = [0] * need
        for i, x in enumerate(a):
            if x:
                for j, y in enumerate(b):
                    res[i + j] = (res[i + j] + x * y) % MOD
        return res

    n = 1
    while n < need:
        n <<= 1

    fa = a + [0] * (n - len(a))
    fb = b + [0] * (n - len(b))

    ntt(fa)
    ntt(fb)
    for i in range(n):
        fa[i] = fa[i] * fb[i] % MOD
    ntt(fa, True)

    return fa[:need]


def main():
    input = sys.stdin.readline
    N = int(input())
    S = input().strip()
    L = 2 * N

    fact = [1] * (N + 1)
    for i in range(1, N + 1):
        fact[i] = fact[i - 1] * i % MOD

    invfact = [1] * (N + 1)
    invfact[N] = pow(fact[N], MOD - 2, MOD)
    for i in range(N, 0, -1):
        invfact[i - 1] = invfact[i] * i % MOD

    # Store all prefixes where #B <= #W.
    # A state with no "backward" pair crossing the current cut is possible
    # exactly at such prefixes.
    events = []
    b = w = 0
    for ch in S:
        if ch == 'B':
            b += 1
        else:
            w += 1
        if b <= w:
            events.append((b, w, w - b))

    m = len(events)

    # val[i] is gradually transformed into the first-return count F_i.
    val = [0] * m
    for i, (b, w, h) in enumerate(events):
        # Number of arbitrary matchings that end with zero open backward edges.
        val[i] = fact[w] * invfact[h] % MOD

    sys.setrecursionlimit(1 << 20)

    def apply_direct(l, mid, r):
        for j in range(mid, r):
            wj = events[j][1]
            total = 0
            for i in range(l, mid):
                fi = val[i]
                if fi:
                    bi = events[i][0]
                    total += fi * fact[wj - bi]
            total %= MOD
            if total:
                val[j] = (val[j] - total * invfact[events[j][2]]) % MOD

    def apply_ntt(l, mid, r):
        min_b = events[l][0]
        max_w = events[r - 1][1]
        span = max_w - min_b

        a = [0] * (events[mid - 1][0] - min_b + 1)
        for i in range(l, mid):
            fi = val[i]
            if fi:
                a[events[i][0] - min_b] = (a[events[i][0] - min_b] + fi) % MOD

        kernel = fact[:span + 1]
        c = convolution(a, kernel)

        for j in range(mid, r):
            idx = events[j][1] - min_b
            if idx < len(c):
                add = c[idx]
                if add:
                    val[j] = (val[j] - add * invfact[events[j][2]]) % MOD

    def cdq(l, r):
        if r - l <= 1:
            return

        mid = (l + r) >> 1
        cdq(l, mid)

        left_count = mid - l
        right_count = r - mid

        # Small ranges are faster with direct computation.
        if left_count * right_count <= 5000:
            apply_direct(l, mid, r)
        else:
            apply_ntt(l, mid, r)

        cdq(mid, r)

    cdq(0, m)

    # The last eligible prefix is always the complete string.
    print(val[-1] % MOD)


if __name__ == "__main__":
    main()
