from bisect import bisect_left

def main():
    input = sys.stdin.readline
    N, X = map(int, input().split())

    dp = [[-1] * (X + 1) for _ in range(3)]
    for v in range(3):
        dp[v][0] = 0

    total_a = [0, 0, 0]

    for _ in range(N):
        v, a, c = map(int, input().split())
        v -= 1
        total_a[v] += a

        d = dp[v]
        for cal in range(X, c - 1, -1):
            prev = d[cal - c]
            if prev >= 0:
                value = prev + a
                if value > d[cal]:
                    d[cal] = value

    # Make each DP array represent the maximum vitamin amount
    # achievable within at most cal calories.
    for v in range(3):
        d = dp[v]
        for cal in range(1, X + 1):
            if d[cal] < d[cal - 1]:
                d[cal] = d[cal - 1]

    def possible(target):
        needed = 0
        for v in range(3):
            cost = bisect_left(dp[v], target)
            if cost > X:
                return False
            needed += cost
        return needed <= X

    low = 0
    high = min(total_a) + 1

    while high - low > 1:
        mid = (low + high) // 2
        if possible(mid):
            low = mid
        else:
            high = mid

    print(low)

