import sys

class UnionFind:
    def __init__(self, n):
        self.parent = list(range(n))
        self.size = [1] * n

    def find(self, x):
        while self.parent[x] != x:
            self.parent[x] = self.parent[self.parent[x]]
            x = self.parent[x]
        return x

    def union(self, a, b):
        a = self.find(a)
        b = self.find(b)
        if a == b:
            return False
        if self.size[a] < self.size[b]:
            a, b = b, a
        self.parent[b] = a
        self.size[a] += self.size[b]
        return True

def main():
    data = list(map(int, sys.stdin.buffer.read().split()))
    n, m = data[0], data[1]

    uf = UnionFind(n)
    answer = 0

    for i in range(m):
        u = data[2 + 2 * i] - 1
        v = data[3 + 2 * i] - 1
        if not uf.union(u, v):
            answer += 1

    print(answer)

if __name__ == "__main__":
    main()
