import sys

def mat_mul(A, B, mod):
    n = len(A)
    C = [[0] * n for _ in range(n)]
    rng = range(n)

    for i in rng:
        ci = C[i]
        ai = A[i]
        for k in rng:
            x = ai[k]
            if x == 0:
                continue
            bk = B[k]
            for j in rng:
                ci[j] += x * bk[j]
        for j in rng:
            ci[j] %= mod

    return C

def mat_pow(A, e, mod):
    n = len(A)
    R = [[0] * n for _ in range(n)]
    for i in range(n):
        R[i][i] = 1

    while e > 0:
        if e & 1:
            R = mat_mul(R, A, mod)
        e >>= 1
        if e:
            A = mat_mul(A, A, mod)

    return R

def main():
    data = list(map(int, sys.stdin.buffer.read().split()))
    if not data:
        return

    it = iter(data)
    n = next(it)
    p = next(it)
    A = [[next(it) for _ in range(n)] for _ in range(n)]

    # When p = 2, every zero can only be replaced by 1,
    # and all nonzero entries are also 1. Thus B is the all-ones matrix.
    if p == 2:
        v = n & 1
        line = " ".join([str(v)] * n)
        print("\n".join([line] * n))
        return

    k_zeros = sum(x == 0 for row in A for x in row)

    # Paths using no zero entries contribute A^p.
    ans = mat_pow(A, p, p)

    if p == 3:
        # A zero edge used twice can contribute.
        # For a diagonal zero (u,u), the remaining fixed edge may enter or leave u.
        for u in range(n):
            if A[u][u] == 0:
                for v in range(n):
                    if A[u][v] != 0:
                        ans[u][v] = (ans[u][v] + A[u][v]) % p
                    if A[v][u] != 0:
                        ans[v][u] = (ans[v][u] + A[v][u]) % p

        # For a non-diagonal zero edge u -> v, the only possible path is
        # u -> v -> u -> v, requiring the fixed reverse edge v -> u.
        for u in range(n):
            for v in range(n):
                if u != v and A[u][v] == 0 and A[v][u] != 0:
                    ans[u][v] = (ans[u][v] + A[v][u]) % p
    else:
        # For p > 3, only a diagonal zero edge can be used p-1 times.
        for u in range(n):
            if A[u][u] == 0:
                for v in range(n):
                    if A[u][v] != 0:
                        ans[u][v] = (ans[u][v] + A[u][v]) % p
                    if A[v][u] != 0:
                        ans[v][u] = (ans[v][u] + A[v][u]) % p

    # Each zero entry contributes a factor of -1 after summation.
    if k_zeros & 1:
        for i in range(n):
            for j in range(n):
                ans[i][j] = (-ans[i][j]) % p

    print("\n".join(" ".join(map(str, row)) for row in ans))

if __name__ == "__main__":
    main()
