def encrypt(s):
    """Return the string with each letter shifted forward by four places."""
    result = []

    for char in s:
        if "a" <= char <= "z":
            result.append(chr((ord(char) - ord("a") + 4) % 26 + ord("a")))
        elif "A" <= char <= "Z":
            result.append(chr((ord(char) - ord("A") + 4) % 26 + ord("A")))
        else:
            result.append(char)

    return "".join(result)
