import sys


def mat_mul(x, y, mod):
    n = len(x)
    res = [[0] * n for _ in range(n)]

    for i in range(n):
        ri = res[i]
        xi = x[i]
        for k, a in enumerate(xi):
            if a:
                yk = y[k]
                for j in range(n):
                    ri[j] += a * yk[j]
        for j in range(n):
            ri[j] %= mod

    return res


def mat_pow(a, e, mod):
    n = len(a)
    res = [[0] * n for _ in range(n)]
    for i in range(n):
        res[i][i] = 1

    while e:
        if e & 1:
            res = mat_mul(res, a, mod)
        a = mat_mul(a, a, mod)
        e >>= 1

    return res


