        b = [[1 if a[i][j] == 0 else a[i][j] for j in range(n)]
             for i in range(n)]
        ans = mat_mul(b, b, 2)
        for row in ans:
            print(*row)
        return

    zero_edges = []
    c = [[0] * n for _ in range(n)]

    for i in range(n):
        for j in range(n):
            if a[i][j] == 0:
                zero_edges.append((i, j))
            else:
                c[i][j] = a[i][j] % p

    ans = mat_pow(c, p, p)

    # Add terms in which one zero entry is used p-1 times.
    if p == 3:
        for u, v in zero_edges:
            if u == v:
                for i in range(n):
                    ans[i][u] += c[i][u]
                for j in range(n):
                    ans[u][j] += c[u][j]
            else:
                ans[u][v] += c[v][u]
    else:
        for u, v in zero_edges:
            if u == v:
                for i in range(n):
                    ans[i][u] += c[i][u]
                for j in range(n):
                    ans[u][j] += c[u][j]

    sign = 1 if len(zero_edges) % 2 == 0 else p - 1

    for i in range(n):
        for j in range(n):
            ans[i][j] = (ans[i][j] * sign) % p
        print(*ans[i])


