def factorize(n: int) -> List[int]:
    """Return prime factors of n in ascending order."""
    if n < 1:
        raise ValueError("factorization is defined only for positive integers")

    factors = []
    divisor = 2

    while divisor * divisor <= n:
        while n % divisor == 0:
            factors.append(divisor)
            n //= divisor
        divisor += 1

    if n > 1:
        factors.append(n)

    return factors
