def intersection(interval1, interval2):
    """Return "YES" if the length of the intersection is prime, otherwise "NO"."""
    start = max(interval1[0], interval2[0])
    end = min(interval1[1], interval2[1])
    length = end - start

    if length < 2:
        return "NO"

    divisor = 2
    while divisor * divisor <= length:
        if length % divisor == 0:
            return "NO"
        divisor += 1

    return "YES"
