MOD = 998244353

def main():
    data = list(map(int, sys.stdin.buffer.read().split()))
    n = data[0]
    a = data[1:]

    exponents = {}

    for i, x in enumerate(a):
        d = 2
        while d * d <= x:
            if x % d == 0:
                cnt = 0
                while x % d == 0:
                    x //= d
                    cnt += 1
                if d not in exponents:
                    exponents[d] = [0] * (n - 1)
                exponents[d][i] = cnt
            d += 1
        if x > 1:
            if x not in exponents:
                exponents[x] = [0] * (n - 1)
            exponents[x][i] = 1

    answer = 1

    for p, edges in exponents.items():
        total_exp = sum(edges)
        max_edge_exp = max(edges)

        max_power = max(total_exp, n * max_edge_exp)
        powers = [1] * (max_power + 1)
        p_mod = p % MOD
        for i in range(1, max_power + 1):
            powers[i] = powers[i - 1] * p_mod % MOD

        dp = [0] * (total_exp + 1)
        dp[0] = 1

        for edge_idx, e in enumerate(edges):
            if e == 0:
                ndp = [0] * (total_exp + 1)
                for h, value in enumerate(dp):
                    if value:
                        ndp[h] = value * powers[h] % MOD
                dp = ndp
                continue

            position_count = edge_idx + 1
            ndp = [0] * (total_exp + 1)

            for h, value in enumerate(dp):
                if not value:
                    continue

                # The valuation decreases by e.
                if h >= e:
                    nh = h - e
                    ndp[nh] = (ndp[nh] + value * powers[nh]) % MOD
                else:
                    shift = e - h
                    weight = powers[position_count * shift]
                    ndp[0] = (ndp[0] + value * weight) % MOD

                # The valuation increases by e.
                nh = h + e
                ndp[nh] = (ndp[nh] + value * powers[nh]) % MOD

            dp = ndp

        factor_sum = sum(dp) % MOD
        answer = answer * factor_sum % MOD

    print(answer)

