import sys

MOD = 998244353

def main():
    input = sys.stdin.buffer.readline

    H, W = map(int, input().split())
    N = H * W

    A = []
    for _ in range(H):
        A.extend(map(int, input().split()))

    Q, sh, sw = map(int, input().split())
    sh -= 1
    sw -= 1

    # Forward DP:
    # fw[v] = sum of products of all paths from (1,1) to v.
    fw = [0] * N
    for r in range(H):
        base = r * W
        for c in range(W):
            i = base + c
            if i == 0:
                fw[i] = A[i]
            else:
                s = 0
                if r:
                    s += fw[i - W]
                if c:
                    s += fw[i - 1]
                fw[i] = (A[i] * s) % MOD

    # Backward DP:
    # bw[v] = sum of products of all paths from v to (H,W).
    bw = [0] * N
    for r in range(H - 1, -1, -1):
        base = r * W
        for c in range(W - 1, -1, -1):
            i = base + c
            if i == N - 1:
                bw[i] = A[i]
            else:
                s = 0
                if r + 1 < H:
                    s += bw[i + W]
                if c + 1 < W:
                    s += bw[i + 1]
                bw[i] = (A[i] * s) % MOD

    ans = fw[-1]
    out = []

    for _ in range(Q):
        d, a_str = input().split()
        a = int(a_str)

        if d == b'L':
            sw -= 1
        elif d == b'R':
            sw += 1
        elif d == b'U':
            sh -= 1
        else:
            sh += 1

        start = sh * W + sw
        old = A[start]

        if old != a:
            # Sum of products before entering this cell.
            if start == 0:
                pre = 1
            else:
                pre = 0
                if sh:
                    pre += fw[start - W]
                if sw:
                    pre += fw[start - 1]
                pre %= MOD

            # Sum of products after leaving this cell.
            if start == N - 1:
                post = 1
            else:
                post = 0
                if sh + 1 < H:
                    post += bw[start + W]
                if sw + 1 < W:
                    post += bw[start + 1]
                post %= MOD

            ans = (ans + (a - old) * pre * post) % MOD
            A[start] = a

            # Update forward DP values in the southeast direction.
            q = [start]
            head = 0
            while head < len(q):
                i = q[head]
                head += 1
                r, c = divmod(i, W)

                if i == 0:
                    nv = A[i]
                else:
                    s = 0
                    if r:
                        s += fw[i - W]
                    if c:
                        s += fw[i - 1]
                    nv = (A[i] * s) % MOD

                if nv != fw[i]:
                    fw[i] = nv
                    if c + 1 < W:
                        q.append(i + 1)
                    if r + 1 < H:
                        q.append(i + W)

            # Update backward DP values in the northwest direction.
            q = [start]
            head = 0
            while head < len(q):
                i = q[head]
                head += 1
                r, c = divmod(i, W)

                if i == N - 1:
