import sys


def mat_mul(x, y, mod):
    n = len(x)
    res = [[0] * n for _ in range(n)]

    for i in range(n):
        ri = res[i]
        xi = x[i]
        for k, a in enumerate(xi):
            if a:
                yk = y[k]
                for j in range(n):
                    ri[j] += a * yk[j]
        for j in range(n):
            ri[j] %= mod

    return res


def mat_pow(a, e, mod):
    n = len(a)
    res = [[0] * n for _ in range(n)]
    for i in range(n):
        res[i][i] = 1

    while e:
        if e & 1:
            res = mat_mul(res, a, mod)
        a = mat_mul(a, a, mod)
        e >>= 1

    return res


def main():
    data = list(map(int, sys.stdin.buffer.read().split()))
    if not data:
        return

    n, p = data[0], data[1]
    vals = data[2:]
    a = [vals[i * n:(i + 1) * n] for i in range(n)]

    if p == 1:
        print("\n".join(["0"] * n))
        return

    if p == 2:
        b = [[1 if a[i][j] == 0 else a[i][j] for j in range(n)]
             for i in range(n)]
        ans = mat_mul(b, b, 2)
        for row in ans:
            print(*row)
        return

    zero_edges = []
    c = [[0] * n for _ in range(n)]

    for i in range(n):
        for j in range(n):
            if a[i][j] == 0:
                zero_edges.append((i, j))
            else:
                c[i][j] = a[i][j] % p

    ans = mat_pow(c, p, p)

    # Add terms in which one zero entry is used p-1 times.
    if p == 3:
        for u, v in zero_edges:
            if u == v:
                for i in range(n):
                    ans[i][u] += c[i][u]
                for j in range(n):
                    ans[u][j] += c[u][j]
            else:
                ans[u][v] += c[v][u]
    else:
        for u, v in zero_edges:
            if u == v:
                for i in range(n):
                    ans[i][u] += c[i][u]
                for j in range(n):
                    ans[u][j] += c[u][j]

    sign = 1 if len(zero_edges) % 2 == 0 else p - 1

    for i in range(n):
